"""Quiz pools: 6 questions per skill, 5 drawn per attempt, options shuffled. Quizzes can prove at most level 3."""
from . import Assignment, Q

DRAW = 5


def quiz(skill, title, summary, pool, minutes=10):
    return Assignment(slug=f"quiz-{skill}", skill=skill, kind="quiz", title=title, summary=summary, ceiling=3, minutes=minutes,
                      instructions="Choose one answer per question. Questions and answer order change on every attempt. "
                                   "A quiz can prove up to level 3 (Intermediate); harder levels need a practical assignment.",
                      spec={"pool": pool, "draw": DRAW})


